/**
 * @brief Calculates the nth number of a custom Tribonacci-like sequence using recursion.
 *
 * The sequence is defined as:
 * F(0) = 0
 * F(1) = -1
 * F(2) = -1
 * F(n) = F(n-1) + F(n-2) + F(n-3) for n > 2
 *
 * This recursive implementation is simple to understand but highly inefficient
 * for larger 'n' due to redundant calculations. Its time complexity is O(3^n).
 *
 * @param n The index of the number to find (n must be non-negative).
 * @return The nth number in the sequence, or a placeholder (0) if n is negative,
 *         with an error message printed to std::cerr.
 */
int tribonacciRecursive(int n) {
    // Input validation for negative numbers
    if (n < 0) {
        std::cerr << "Error: Input 'n' cannot be negative for this sequence." << std::endl;
        // Returning a placeholder. The main function should check 'n' itself
        // to determine whether to print a valid result.
        return 0;
    }

    // Base cases (the first three numbers given in the problem)
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return -1;
    }
    if (n == 2) {
        return -1;
    }

    // Recursive step: sum of the three preceding numbers
    return tribonacciRecursive(n - 1) + tribonacciRecursive(n - 2) + tribonacciRecursive(n - 3);
}

int main() {
    int n;

    // Prompt the user for input
    std::cout << "Enter the value of n (non-negative) to find the nth number in the sequence: ";
    std::cin >> n;

    // Call the recursive function only if n is valid
    if (n >= 0) {
        int result = tribonacciRecursive(n);
        std::cout << "The " << n << "th number in the sequence is: " << result << std::endl;
    } else {
        // If n was negative, an error message has already been printed by tribonacciRecursive().
        // We just ensure main doesn't print a "result" in this case.
        return 1; // Indicate an error occurred
    }

    return 0; // Indicate successful execution
}
```

